type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };
type DebitError = { code: "frozen" } | { code: "insufficient_funds"; shortBy: number };

function debit(balance: number, frozen: boolean, amount: number): Result<number, DebitError> {
  if (frozen) return { ok: false, error: { code: "frozen" } };
  if (amount > balance) return { ok: false, error: { code: "insufficient_funds", shortBy: amount - balance } };
  return { ok: true, value: balance - amount };
}

const attempts: [number, boolean, number][] = [[5000, false, 2000], [5000, false, 7500], [5000, true, 100]];
for (const [balance, frozen, amount] of attempts) {
  const result = debit(balance, frozen, amount);
  if (result.ok) console.log(`balance ${result.value}`);
  else if (result.error.code === "insufficient_funds") console.log(`short by ${result.error.shortBy}`);
  else console.log("wallet frozen");
}
